<?php $filters=array_intersect_key($_GET,array_flip(['department','programme','search']));$modules=spModuleList($u,$filters);$pages=max(1,(int)ceil(count($modules)/5));$pn=min($pages,max(1,(int)($_GET['p']??1)));?>
<section class="card"><h2><?=spBrowse($u)?'Attendance modules':'My modules'?></h2><p>Use the same module each day or week. Select Enter attendance, choose your next dates, check absences and submit. Previously recorded sessions are skipped.</p>
<form method="get"><input type="hidden" name="page" value="sa_portal"><div class="form-grid"><?php acField('search','Staff name / module code',$filters,[],'text',false);acField('department','Department',$filters,departments(),'text',false);acField('programme','Programme',$filters,examProgrammes(),'text',false);?></div><button>Filter</button> <a href="?page=sa_portal">Clear</a></form>
<div class="table-wrap"><table><thead><tr><th>Module</th><th>Programme / cohort</th><th>Staff</th><th>Actions</th></tr></thead><tbody><?php foreach(array_slice($modules,($pn-1)*5,5) as $m):$hasDraft=(bool)one('SELECT record_id FROM attendance_drafts WHERE record_id=?',[$m['id']]);?><tr><td><?=e($m['module_code'].' · '.$m['module_name'])?><?php if($hasDraft):?><p class="notice">Draft ready — check and submit</p><?php endif;?></td><td><?=e($m['department'].' · '.$m['programme'].' · '.$m['academic_year'].' · '.$m['study_year'].' / '.$m['semester'].' · '.$m['section'])?></td><td><?=e($m['tutor_name'])?></td><td><a class="button secondary" href="?page=sa_record&id=<?=$m['id']?>">Timetable</a> <a class="button" href="?page=sa_record&id=<?=$m['id']?>#enter-attendance"><?=$hasDraft?'Continue draft':'Enter attendance'?></a> <a class="button secondary" href="?page=sa_record&id=<?=$m['id']?>#recorded-attendance">View recorded attendance</a><?php if(acAdmin($u)):?><details><summary class="button danger-button">Delete module and all attendance</summary><p>Deletes this module, regular/special timetable, attendance and drafts. Staff can create it again.</p><?php spForm('sa_plan_module_delete',$m);?><label class="period-delete-confirm"><input type="checkbox" name="confirmed" value="1" required><span>I confirm deletion of <?=e($m['module_code'])?> and all its attendance.</span></label><button class="danger-button">Delete permanently from active records</button></form></details><?php elseif(spDeleteAllowed($u,$m)):?> <a class="button danger-button" href="?page=sa_record&id=<?=$m['id']?>#delete-attendance">Delete attendance</a><?php endif;?></td></tr><?php endforeach;if(!$modules):?><tr><td colspan="4">No matching modules.</td></tr><?php endif;?></tbody></table></div>
<p><?=count($modules)?> modules · Page <?=$pn?> of <?=$pages?> <?php foreach(['Previous'=>$pn-1,'Next'=>$pn+1] as $label=>$n)if($n>=1&&$n<=$pages):?><a class="button secondary" href="?<?=e(http_build_query($filters+['page'=>'sa_portal','p'=>$n]))?>"><?=e($label)?></a> <?php endif;?></p></section>
